select 'T-11a is_owner_of_account shape' as check, p.prosecdef secdef, p.provolatile vol, p.proconfig::text cfg, has_function_privilege('anon','public.is_owner_of_account(uuid)','EXECUTE') anon_exec, has_function_privilege('authenticated','public.is_owner_of_account(uuid)','EXECUTE') auth_exec, (p.proacl::text ~ '(^|\{|,)=X/') public_exec from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_owner_of_account';
select 'T-11a my_business_ids def' as check, pg_get_functiondef('public.my_business_ids'::regproc) def;
select 'T-11b policies per table x cmd' as check, tablename, cmd, count(*) filter (where permissive='PERMISSIVE') permissive_n, string_agg(policyname, ',' order by policyname) names from pg_policies where schemaname='public' group by tablename, cmd order by tablename, cmd;
select 'T-11b totals' as check, count(*) total, count(*) filter (where permissive='PERMISSIVE') permissive, count(*) filter (where tablename='user_data') user_data_policies, count(*) filter (where tablename='audit_logs' and cmd='SELECT') audit_logs_select, count(*) filter (where policyname ~ 'owner') owner_policies from pg_policies where schemaname='public';
select 'T-11c policy bodies referencing user_roles' as check, count(*) n from pg_policies where schemaname='public' and (coalesce(qual,'')||coalesce(with_check,'')) ~* 'user_roles';
select 'T-11d one-admin partial unique index' as check, indexname, indexdef from pg_indexes where schemaname='public' and tablename='user_businesses' and indexdef ~* 'unique' and indexdef ~* 'admin';
select 'T-11e grants on user_data/audit_logs/system_config to anon/authenticated/PUBLIC' as check, grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema='public' and table_name in ('user_data','audit_logs','system_config') and grantee in ('anon','authenticated','PUBLIC') order by 2,1,3;
select 'T-11e default ACLs' as check, pg_get_userbyid(d.defaclrole) owner, coalesce(n.nspname,'') nsp, d.defaclobjtype objtype, d.defaclacl::text acl from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace order by 1,2,3;
select 'T-11 handle_new_user revoked' as check, has_function_privilege('anon','public.handle_new_user()','EXECUTE') anon_exec, has_function_privilege('authenticated','public.handle_new_user()','EXECUTE') auth_exec;
select 'T-19 admin RPC shape' as check, p.proname, p.prosecdef secdef, p.proconfig::text cfg, has_function_privilege('anon',p.oid,'EXECUTE') anon_exec, has_function_privilege('authenticated',p.oid,'EXECUTE') auth_exec, (p.proacl::text ~ '(^|\{|,)=X/') public_exec from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('tenant_stores','admin_stores','admin_members','admin_billing_status','admin_audit') order by p.proname;
select 'T-21 handle_new_user def' as check, pg_get_functiondef('public.handle_new_user'::regproc) def;
select 'ownership FK' as check, conname, confdeltype from pg_constraint where conrelid='public.accounts'::regclass and contype='f';
